gold.schema_ddl:
CREATE TABLE vendite (
    id SERIAL PRIMARY KEY,
    codice_fiscale_cliente TEXT NOT NULL,
    data_vendita DATE NOT NULL DEFAULT CURRENT_DATE,
    importo_totale NUMERIC(12,2) CHECK (importo_totale >= 0),
    stato TEXT CHECK (stato IN ('completato', 'annullato', 'in_corso'))
);

CREATE TABLE prodotti (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    descrizione TEXT,
    prezzo_unitario NUMERIC(10,2) CHECK (prezzo_unitario >= 0)
);

CREATE TABLE righe_vendita (
    id SERIAL PRIMARY KEY,
    vendita_id INT NOT NULL REFERENCES vendite(id),
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT CHECK (quantita > 0),
    prezzo_unitario NUMERIC(10,2) CHECK (prezzo_unitario >= 0)
);
